  const monday = s => { const d = D(s); d.setDate(d.getDate() - (d.getDay() + 6) % 7); return iso(d); };
  const at = (s, t) => { const d = D(s); const [h, m] = t.split(':').map(Number); d.setHours(h, m); return d; };
  const TODAY = iso(NOW), dmy = s => s.split('-').reverse().join('/');
  const long = s => D(s).toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  const short = s => D(s).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
  const TIMES = Array.from({ length: 16 }, (_, i) => `${pad(9 + Math.floor(i / 2))}:${i % 2 ? '30' : '00'}`);
  const money = n => '£' + Number(n).toFixed(2);
