  const live = a => a.status === 'confirmed' && a.mode === 'online' && start(a) - NOW <= 10 * 6e4 && NOW - start(a) < 30 * 6e4;
  const pending = a => ['reserved', 'failed', 'choose'].includes(a.status);
  const past = a => ['completed', 'dna', 'cancelled'].includes(a.status);
  const tone = a => a.status === 'choose' ? 'purple' : pending(a) ? 'orange' : ['dna', 'cancelled'].includes(a.status) ? 'red' : a.status === 'completed' ? 'green' : '';

  /* every appointment with a fee has an invoice in Billing, so both screens agree */
