  const success = (title, text, a, kindLabel) => App.dialog(`<div class="pt-dlg pa-ok"><span class="pa-okic"><i class="ri-check-line"></i></span><h2 id="dlg-title">${title}</h2><p class="body2" style="margin:0">${text}</p><div class="pa-okbox">${[['Service', a.svc], [kindLabel, mode(a)[2].replace(' Appointment', ' consultation')], ['Date &amp; time', `${short(a.date)} · ${a.t}`]].map(([k, x]) => `<div><span>${k}</span><b>${esc(x)}</b></div>`).join('')}</div><div class="g2" style="gap:12px"><button class="btn outlined lg" data-act="pa-ok-view" data-id="${a.id}">View appointment</button><button class="btn primary lg" data-act="pa-ok-done">Done</button></div></div>`, { width: 440 });
