  const STEPS = [['svc', 'Service'], ['staff', 'Specialist'], ['type', 'Booking Type'], ['time', 'Date & time'], ['pay', 'Payment']];
  const stepper = () => { const i = STEPS.findIndex(s => s[0] === F.step); return `<ol class="pa-steps">${STEPS.map(([k, t], j) => `<li class="${j < i ? 'done' : j === i ? 'on' : ''}"><span>${j < i ? '<i class="ri-check-line"></i>' : j + 1}</span>${t}</li>`).join('')}</ol>`; };
  acts['pa-newbook'] = () => { F.kind = null; };
  App.route('/me/book', () => { flow('book', 'new'); const back = '<button class="btn outlined lg" data-act="pf-back"><i class="ri-arrow-left-s-line"></i>Back</button>', cancel = '<a class="btn outlined lg pa-xo" href="#/appointments" data-act="pf-reset"><i class="ri-close-line"></i>Cancel Booking</a>';
    const pick = (lbl, icon, val, step) => `<div class="card pa-picked"><span class="pa-ic"><i class="${icon}"></i></span><div class="grow"><small>${lbl}</small><b>${esc(val)}</b></div><button class="btn text sm brand" data-act="pf-go" data-v="${step}">Change<i class="ri-pencil-line"></i></button></div>`;
    const cr = crumbs([['Appointments'], ...(F.step === 'svc' ? [['Select Service & Type']] : [['Select Service & Type', '#/me/book'], ...(F.step === 'staff' || F.step === 'type' ? [['Select Specialist']] : [['Select Specialist', '#/me/book'], [F.step === 'pay' ? 'Secure Payment' : 'Book Appointment']])])]);
    if (F.step === 'svc') { const l = SVCS.filter(s => !F.sq || (s[1] + s[2]).toLowerCase().includes(F.sq.toLowerCase()));
      return cr + stepper() + `<div class="me-head"><h1>Select Service</h1><p>Choose the care you’d like to book</p></div><section class="card card-pad stack g16"><div class="filters">${App.field('Service', `<input data-in="pf-sq" value="${esc(F.sq)}" placeholder="Search Service here…"><span class="adorn"><i class="ri-search-line"></i></span>`, { cls: 'search' })}<span class="grow"></span><button class="clear-btn" data-act="pf-clr"><i class="ri-close-line"></i>Clear filters</button></div>
        ${l.length ? `<div class="pa-grid">${l.map(s => `<article class="pa-spec pa-svc ${F.svc === s[1] ? 'on' : ''}" data-act="pf-svcpick" data-v="${s[1]}"><div class="row g12"><span class="pa-ic"><i class="ri-heart-add-line"></i></span><div class="grow"><b>${s[1]}</b><small>30 mins</small></div><span class="pa-radio" aria-hidden="true"></span></div><p class="body2" style="margin:0">${s[2]}</p><div class="pa-next"><i class="ri-calendar-line"></i><div class="grow"><small>Next Available</small><b>${nextFree(s[4][0])}</b></div><b class="pa-price">£${s[3]}</b></div><button class="btn primary block" data-act="pf-svc" data-v="${s[1]}">View Available Specialists<i class="ri-arrow-right-s-line"></i></button></article>`).join('')}</div>` : '<div class="pt-empty" style="padding:50px 10px"><span class="soon-icon"><i class="ri-search-eye-line"></i></span><b>No services match your search.</b></div>'}</section><div class="row">${cancel}</div>`; }
    if (F.step === 'staff') return cr + stepper() + `<div class="me-head"><h1>Select Specialist</h1><p>Choose a specialist from the list below to continue</p></div><div class="ap-cons"><div class="stack g16">${pick('Selected Service', 'ri-heart-add-line', F.svc, 'svc')}${staffGrid(true)}<div class="row between">${back}${cancel}</div></div>${summary()}</div>`;
    if (F.step === 'type') { const s = stf(F.sid);
      return cr + stepper() + `<div class="me-head"><h1>Select Booking Type</h1><p>Choose how you would like to attend your appointment</p></div><div class="ap-cons"><div class="stack g16"><div class="g2" style="gap:12px">${pick('Selected Service', 'ri-heart-add-line', F.svc, 'svc')}${pick('Specialist', 'ri-stethoscope-line', s[1], 'staff')}</div>
        <div class="pa-grid three">${Object.entries(MODES).map(([k, m]) => `<article class="pa-spec ${s[3].includes(k) ? '' : 'dis'}"><div class="row g12"><span class="pa-ic"><i class="${m[3]}"></i></span><div><b style="font-size:17px">${m[2]}</b><small>30 mins</small></div></div><p class="body2" style="margin:0">${m[4]}</p><div class="pa-next"><i class="ri-hourglass-line"></i><b class="grow">Available Slots</b><b class="pa-price">${s[3].includes(k) ? weekCount(s[0]) : 0}</b></div><button class="btn primary block" data-act="pf-mode" data-v="${m[0]}" ${s[3].includes(k) ? '' : 'disabled'}>${s[3].includes(k) ? 'Select' : 'Not offered'}<i class="ri-arrow-right-s-line"></i></button></article>`).join('')}</div><div class="row between">${back}${cancel}</div></div>${summary()}</div>`; }
    if (F.step === 'time') return cr + stepper() + bookHead() + `<div class="ap-cons"><div class="stack g16">${picker()}<div class="row between">${back}${cancel}</div></div>${summary('pf-topay', 'Confirm Appointment')}</div>`;
    return cr + stepper() + payPage({ svc: F.svc, sid: F.sid, mode: F.mode, date: F.slot.d, t: F.slot.t, price: svcOf(F.svc)[3], loc: F.mode === 'f2f' ? CLINIC : '' }, 'pf-pay', true); }, meta);
  ins['pf-sq'] = el => { F.sq = el.value; keep(); const n = App.$('[data-in=pf-sq]'); n.focus(); n.setSelectionRange(n.value.length, n.value.length); };
