  acts['pf-pickmode'] = el => { F.sid = el.dataset.s; F.mode = el.dataset.m; F.slot = null; F.week = firstWeek(F.sid); F.day = F.week; F.view = 'Weekly'; F.step = F.kind === 'book' ? 'time' : 'slot'; App.render(); scrollTo(0, 0); };
  acts['pf-mode'] = el => { F.mode = el.dataset.v; F.slot = null; F.step = 'time'; App.render(); scrollTo(0, 0); };
