  acts['pf-reset'] = () => { F.kind = null; };
  acts['pf-back'] = () => { const order = F.kind === 'book' ? ['svc', 'staff', 'type', 'time', 'pay'] : ['staff', 'slot']; const i = order.indexOf(F.step);
    if (i <= 0) return App.go('#/appointments'); F.step = order[i - 1]; App.render(); scrollTo(0, 0); };

  /* ---------- secure payment (shared by booking, reserved and failed appointments) ---------- */
  const PAY = App.ui.paPay = { method: 'card', save: true };
  const payPage = (a, act, wizard, id) => { const s = stf(a.sid), md = mode(a);
    return `${wizard ? '' : crumbs([['Appointments'], ['Book Appointment', id ? `#/me/appointments/${id}/confirm` : '#/appointments'], ['Secure Payment']])}<div class="me-head"><h1>Secure Payment</h1><p>Your payment information is encrypted and secure</p></div><div class="me-pay"><section class="card card-pad stack g12">
      ${wizard ? '' : '<div class="row g12"><span class="bl-dic"><i class="ri-lock-line"></i></span><div><b>Secure Payment</b><br><small class="caption">Your payment information is encrypted and secure</small></div></div>'}<b class="sub2">Payment Method</b><div class="row g8">${[['card', 'Credit/Debit Card'], ['paypal', 'PayPal']].map(([k, t]) => `<button class="btn ${PAY.method === k ? 'primary' : 'outlined pt-dark'}" style="min-width:150px" data-act="pa-pm" data-v="${k}">${t}</button>`).join('')}</div>
      ${PAY.method === 'card' ? `<form class="stack g12" id="pt-form" onsubmit="return false">${PT.F('Card Number', 'cn', '', { req: true, ph: '1234 5678 9012 3456' })}${PT.F('Cardholder Name', 'ch', 'Ahmed Raza', { req: true })}<div class="g2">${PT.F('Expiry Date', 'ex', '', { req: true, ph: 'MM/YY' })}${PT.F('CVV', 'cvv', '', { req: true, ph: '123' })}</div>${wizard ? PT.S('Country', 'country', ['England', 'Scotland', 'Wales', 'Northern Ireland'], 'England') : ''}</form><label class="cbx"><input type="checkbox" data-ch="pa-save" ${PAY.save ? 'checked' : ''}>Save card details for future appointments</label>` : '<div class="pt-note"><i class="ri-paypal-line"></i>You’ll be taken to PayPal to approve the payment, then brought back here.</div>'}
      <div class="${wizard ? 'g2' : 'stack'}" style="gap:10px">${wizard ? '<button class="btn outlined lg" data-act="pf-back">Cancel</button>' : ''}<button class="btn primary lg block" data-act="${act}" data-id="${id || ''}">Pay ${money(a.price)}</button></div><div class="pa-bar blue"><i class="ri-information-line"></i>Your payment is secured with 256-bit SSL encryption. We never store your full card details.</div></section>
      <aside class="card card-pad stack g12"><h2 class="dh2" style="font-size:20px">Booking Summary</h2>${[a.svc && ['ri-heart-add-line', 'Service', a.svc], ['ri-calendar-check-line', 'Appointment Type', md[2]], ['ri-stethoscope-line', 'Clinician', s[1]], ['ri-calendar-line', 'Date', long(a.date)], ['ri-time-line', 'Time', `${a.t} (30 min appointment)`], a.mode === 'f2f' && ['ri-map-pin-line', 'Location', a.loc || CLINIC]].filter(Boolean).map(([i, k, x]) => `<div class="me-bs"><i class="${i}"></i><div><small>${k}</small><b>${esc(x)}</b></div></div>`).join('')}
        <hr style="margin:4px 0"><div class="row between caption"><span>Consultation Fee</span><span>${money(a.price)}</span></div><div class="row between"><b>Total</b><b class="me-due" style="font-size:24px">${money(a.price)}</b></div><div class="me-free"><i class="ri-checkbox-circle-line"></i>Free cancellation up to 48 hours before the appointment</div></aside></div>`; };
  acts['pa-pm'] = el => { PAY.method = el.dataset.v; keep(); }; chs['pa-save'] = el => { PAY.save = el.checked; };
  const charge = (el, done) => { if (PAY.method === 'card') { const d = PT.formData(), bad = []; if (!/^\d{16}$/.test((d.cn || '').replace(/\s/g, ''))) bad.push('cn'); if (!(d.ch || '').trim()) bad.push('ch'); if (!/^(0[1-9]|1[0-2])\/\d\d$/.test((d.ex || '').trim())) bad.push('ex'); if (!/^\d{3,4}$/.test((d.cvv || '').trim())) bad.push('cvv');
      App.$$('#pt-form .field').forEach(fl => { const n = fl.querySelector('[name]'); if (n) fl.classList.toggle('err', bad.includes(n.name)); }); if (bad.length) return App.snack(bad.includes('cn') ? 'Enter the 16-digit card number.' : 'Check the highlighted card details.', 'error'); }
    el.disabled = true; el.innerHTML = '<i class="ri-loader-4-line spin"></i>Processing…'; setTimeout(done, 900); };
