  acts['pf-pay'] = el => charge(el, () => { const s = F; const a = { id: 'pa' + (L.length + 1) + Date.now() % 1000, title: s.svc === 'Weight Management' ? 'Weight Management Consultation' : s.svc, svc: s.svc, kind: 'Initial Assessment', sid: s.sid, mode: s.mode, date: s.slot.d, t: s.slot.t, status: 'confirmed', price: svcOf(s.svc)[3], loc: s.mode === 'f2f' ? CLINIC : '', booked: TODAY };
    L.push(a); paid(a); F.kind = null; v.tab = 'all'; App.go('#/appointments'); success('Booking confirmed', 'The appointment slot has been booked and a confirmation email has been sent to your email.', a, 'Booking type'); });

